//! Help ▸ Third-Party Licences: the notices JBD must ship for the open-source code and fonts it
//! includes (`assets/jbd/THIRD-PARTY-NOTICES.txt`, built into the app so it is always there). The
//! installer also puts the same file next to jbd.exe.

use crate::FilmcraftApp;
use crate::theme::Tokens;

/// The notices, generated by `packaging/windows/notices.ps1` (see docs/jbd/PLAN.md).
pub const NOTICES: &str = include_str!("../../../../assets/jbd/THIRD-PARTY-NOTICES.txt");

pub fn open(app: &mut FilmcraftApp) {
    app.jbd.licences_open = true;
}

pub fn show(app: &mut FilmcraftApp, ctx: &egui::Context) {
    if !app.jbd.licences_open {
        return;
    }
    let t = app.tokens;
    let mut open = true;
    egui::Window::new("Third-party licences")
        .open(&mut open)
        .collapsible(false)
        .resizable(true)
        .default_size([640.0, 520.0])
        .anchor(egui::Align2::CENTER_CENTER, [0.0, 0.0])
        .show(ctx, |ui| {
            ui.label(
                egui::RichText::new("JBD is © Jabrod. It includes open-source software and fonts, used under the licences below.")
                    .font(Tokens::ui(12.0))
                    .color(t.text_dim),
            );
            // the complete list (every Rust library, with its licence text) ships next to jbd.exe
            let full = std::env::current_exe().ok().and_then(|e| e.parent().map(|d| d.join("THIRD-PARTY-NOTICES.txt"))).filter(|p| p.exists());
            if let Some(path) = full {
                let b = ui.button("Open the complete list (every library)");
                app.auto.add("licences.openFull", b.rect, "Open the complete list");
                if b.clicked()
                    && let Some(open) = app.hooks.open_path.as_mut()
                    && let Err(e) = open(&path.to_string_lossy(), false)
                {
                    app.ui.status = e;
                }
            }
            ui.add_space(6.0);
            egui::ScrollArea::vertical().auto_shrink([false, false]).show(ui, |ui| {
                ui.label(egui::RichText::new(NOTICES).font(Tokens::mono(11.0)).color(t.text));
            });
        });
    if !open {
        app.jbd.licences_open = false;
    }
}
